-- Starting catalogue (from the mockup). Re-running replaces these SKUs.
INSERT OR REPLACE INTO products (sku, name, cat, mat, img, finish, size, variants, description, featured, sort) VALUES
('BUF-0001', 'Oval Serving Tray with Brass Handles', 'buffetware', 'Stainless steel', 'assets/img/products/buf-1-oval-serving-tray-brass-handles.webp', 'Mirror-polished steel with antique-brass handles and rim', 'To be confirmed', 'Multiple sizes available', 'An oval stainless-steel tray with a mirror-polished bed, framed by an antique-brass rim and scrolled side handles. Built for buffet counters, canapé service and banquet presentation, it combines everyday durability with a classic, upscale look.', 1, 0),
('BUF-0002', 'Octagonal Beaded Serving Tray', 'buffetware', 'Stainless steel', 'assets/img/products/buf-2-octagonal-beaded-tray.webp', 'Mirror polish with beaded border', 'To be confirmed', 'Square-octagonal and rectangular-octagonal, in several sizes', 'A stainless-steel serving tray with cut corners and a fine beaded border. The flat, polished bed works for platters on a buffet line, for dessert and mithai displays, and for passing drinks during banquet service.', 0, 1),
('BUF-0003', 'Stainless-Steel Lidded Serving Dish', 'buffetware', 'Stainless steel', 'assets/img/products/buf-3-lidded-serving-dish.webp', 'Satin polish', 'To be confirmed', 'To be confirmed', 'A round serving dish with a close-fitting domed lid and knob handle. It keeps curries, rice and sides covered and warm between the kitchen and the table, and suits buffet counters, family-style service and room service.', 0, 2),
('BUF-0004', 'Buffet Serving Tongs', 'buffetware', 'Stainless steel', 'assets/img/products/buf-4-16-serving-tongs-steel-rose-gold-gold.webp', 'Steel, rose gold and gold', '12" and 16" lengths', '12" steel, 16" steel, 16" rose gold, 16" gold', 'Long-handled serving tongs with scalloped grips for clean, controlled service of breads, kebabs, salads and pastries. Choose classic steel, or rose gold and gold finishes to match premium buffet setups.', 1, 3),
('BUF-0005', 'Mini Fry Serving Basket', 'buffetware', 'Stainless steel', 'assets/img/products/buf-5-mini-fry-serving-basket.webp', 'Fine stainless-steel wire mesh', 'To be confirmed', 'Square, rectangular and round mini serving and snack baskets', 'A miniature fry basket with a long angled handle, made for serving fries, pakoras, onion rings and other snacks. A popular presentation piece for cafés, bars and live-counter buffets.', 0, 4),
('TBL-0001', 'Brass Sovereign Thali Set (8 pcs)', 'tableware', 'Brass', 'assets/img/products/tbl-1-brass-sovereign-thali-set.webp', 'Satin brass', 'Thali 32.5 × 32.5 × 4 cm', 'Thali (1), Sovereign katori 100 ml (3), Sovereign rice bowl 200 ml (1), Amrapali glass 300 ml (1), dessert spoon (1)', 'A complete brass thali for traditional Indian dining: a wide rimmed thali with three katoris, a rice bowl, a tall Amrapali glass and a dessert spoon. Ideal for signature thali menus, heritage restaurants and wedding banquets.', 1, 5),
('TBL-0002', 'Bronze Sagan Big Thali Set (10 pcs)', 'tableware', 'Bronze', 'assets/img/products/tbl-2-bronze-sagan-big-thali-set.webp', 'Satin bronze (kansa)', 'Thali 31.5 × 31.5 × 3 cm · approx. 1.9 kg', 'Sagan big thali (1), big katori 200 ml (5), glass 400 ml (1), chutney katori 100 ml (1), halwa plate 200 ml (1), dessert spoon (1). Also available as an 8-piece medium set.', 'A 10-piece bronze (kansa) thali set in the Sagan design, with five katoris, a chutney katori, a halwa plate, a glass and a dessert spoon. Its soft satin finish gives a refined, heritage feel to fine-dining and festive thali service.', 0, 6),
('TBL-0003', 'Brass Serving Handi', 'tableware', 'Brass', 'assets/img/products/tbl-3-brass-serving-handi.webp', 'Satin brass', '400 ml (12 × 12 × 6 cm) · 600 ml (15 × 15 × 6.5 cm) · 900 ml (17 × 17 × 6 cm)', '400 ml, 600 ml, 900 ml · matching brass lids available', 'A classic serving handi with a rounded belly, rolled rim and twin side handles, for bringing dals, curries and biryani to the table. Available in three sizes, with matching lids for covered service.', 0, 7),
('TBL-0004', 'Sagan Brass Katoris', 'tableware', 'Brass', 'assets/img/products/tbl-4-sagan-brass-katoris.webp', 'Satin brass', '200 ml · 150 ml · 100 ml', 'Big 200 ml, small 150 ml, chutney 100 ml', 'Rounded brass katoris in the Sagan design, in three sizes for dals, raita, sabzi, chutneys and desserts. Use them on their own or to build out thali service.', 0, 8),
('TBL-0005', 'Brass Dolphin Pitcher with Lid', 'tableware', 'Brass', 'assets/img/products/tbl-5-brass-dolphin-pitcher-with-lid.webp', 'Satin brass with decorative lid knob', '1600 ml · 9 × 9 × 22.5 cm', '1600 ml', 'A tall brass water pitcher with a sculpted spout, curved handle and fitted lid. It holds 1.6 litres, making it practical for table water service and a striking piece on the dining room floor.', 0, 9),
