('PNP-0001', 'Copper Sauce Pan with Brass Handle', 'potspans', 'Copper', 'assets/img/products/pnp-1-copper-sauce-pan-brass-handle.webp', 'Hammered copper exterior, polished stainless-steel interior, brass handle', '350 ml (11.5 × 11.5 × 5 cm) · 550 ml (13.5 × 13.5 × 6 cm) · 800 ml (15.5 × 15.5 × 6 cm)', '350 ml, 550 ml, 800 ml', 'A table-service sauce pan with a hammered copper exterior, a stainless-steel lining and a cast brass handle. Good for serving dals, curries and sauces straight to the table, adding warmth and theatre to Indian and continental menus.', 1, 16),
('PNP-0002', 'Copper Wok Pan with Brass Handle', 'potspans', 'Copper', 'assets/img/products/pnp-2-copper-wok-pan-brass-handle.webp', 'Hammered copper exterior, polished stainless-steel interior, brass handle', 'From 13 × 13 × 6.5 cm (300 ml) to 21 × 21 × 10.5 cm (1400 ml)', '300 ml, 450 ml, 600 ml, 800 ml, 1400 ml', 'A wok-style serving pan with a hammered copper body, stainless-steel lining and long brass handle. Available in five sizes, from single portions to sharing dishes, for stir-fries, Indo-Chinese plates and dry preparations.', 0, 17),
('PNP-0003', 'Copper Gravy Bucket Pan', 'potspans', 'Copper', 'assets/img/products/pnp-3-copper-gravy-bucket-pan.webp', 'Hammered copper exterior, polished stainless-steel interior, brass handle', '350 ml (10 × 10 × 10 cm) · 450 ml (11 × 11 × 11.5 cm) · 800 ml (13 × 13 × 16 cm)', '350 ml, 450 ml, 800 ml', 'A tall, footed bucket-style server with a long brass handle, designed for gravies, curries, dals and soups. The hammered copper finish makes it a distinctive piece for table service and buffet counters.', 0, 18),
('PNP-0004', 'Copper Belly Pan with Brass Handle', 'potspans', 'Copper', 'assets/img/products/pnp-4-copper-belly-pan-brass-handle.webp', 'Hammered copper exterior, polished stainless-steel interior, brass handle', 'From 12 × 12 × 5 cm (450 ml) to 18.5 × 18.5 × 7 cm (1450 ml)', '450 ml, 650 ml, 1000 ml, 1450 ml · mini belly pan 300 ml and mini belly bowl 150 ml also available', 'A round-bellied serving pan with a hammered copper body, stainless-steel lining and brass handle. Comes in four sizes for curries, sizzling sides and sharing portions, giving a rustic, premium look to the table.', 0, 19),
('PNP-0005', 'Brass Serving Karahi', 'potspans', 'Brass', 'assets/img/products/pnp-5-brass-serving-karahi.webp', 'Satin brass', '400 ml (13 × 13 × 4.5 cm) · 500 ml (14 × 14 × 4.5 cm) · 600 ml (16 × 16 × 5 cm)', '400 ml, 500 ml, 600 ml · matching brass lids available', 'A traditional twin-handled karahi in brass, sized for table service of karahi dishes, paneer and sabzi. Shallow and wide for an attractive presentation, with matching lids available.', 0, 20);
